        }

        /* Decorations */
        .island-bg-image {
            position: absolute; inset: 0; background-size: cover; background-position: center;
            filter: brightness(0.6) contrast(1.1); transition: opacity 0.5s ease 0.1s, background-image 0.5s ease;
