        @keyframes pulse { 0%, 100% { opacity: 1; transform: scale(1); } 50% { opacity: 0.5; transform: scale(0.8); } }

        .close-btn {
            width: 32px; height: 32px; border-radius: 50%; background: rgba(255, 255, 255, 0.2); border: none; color: white; display: flex; align-items: center; justify-content: center; cursor: pointer; backdrop-filter: blur(4px); transition: background 0.2s; flex-shrink: 0;
        }
        .close-btn:hover { background: white; color: black; }

        /* --- MIDDLE CONTENT AREA --- */
        .content-display-area {
            flex: 1;
            display: flex;
            align-items: flex-end;
