        }

        /* --- MUSIC PLAYER STYLES --- */
        .mp-container { display: flex; align-items: center; gap: 16px; padding-top: 6px; position: relative; }
        .mp-vinyl-area { position: relative; width: 80px; height: 80px; flex-shrink: 0; }
        .mp-vinyl-disc { width: 100%; height: 100%; border-radius: 50%; background: #181818; background-image: radial-gradient(circle at center, #1a1a1a, #000); position: relative; box-shadow: 0 6px 12px rgba(0, 0, 0, 0.4); border: 1px solid rgba(255, 255, 255, 0.1); animation: spin 3s linear infinite; animation-play-state: paused; overflow: hidden; }
        .mp-vinyl-disc.spinning { animation-play-state: running; }
        .mp-vinyl-label { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 30%; height: 30%; background: #f472b6; border-radius: 50%; border: 2px solid #111; overflow: hidden; }
        .mp-vinyl-label img { width: 100%; height: 100%; object-fit: cover; }
        .mp-vinyl-grooves { position: absolute; inset: 10%; border-radius: 50%; border: 1px solid rgba(255, 255, 255, 0.05); background: repeating-radial-gradient(#111 0, #111 2px, #222 3px, #111 4px); opacity: 0.5; }
        @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }

        .mp-interface { flex: 1; display: flex; flex-direction: column; justify-content: center; min-width: 0; gap: 8px; }
