        }
        .mp-loading i { margin-right: 8px; animation: spin 1s linear infinite; }

        input[type=range].mp-slider {
            -webkit-appearance: none; width: 100%; height: 12px; background: transparent; outline: none; cursor: pointer; margin: 0;
            background: rgba(255, 255, 255, 0.1);
            border-radius: 6px;
