    <style>
        /* --- RESET & BASE --- */
        * { box-sizing: border-box; margin: 0; padding: 0; -webkit-font-smoothing: antialiased; }

        html, body { width: 100%; background: transparent; }

        body {
            font-family: 'Inter', sans-serif;
            overflow: auto;
            display: flex;
            justify-content: center;
            align-items: flex-start;
            padding-top: 0px;
            padding-bottom: 0px;
        }

        #root {
            width: 100%;
            display: flex;
            justify-content: center;
        }

        /* --- UTILS --- */
        .hidden-scrollbar::-webkit-scrollbar { display: none; }
        .hidden-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }

        /* --- SWISS ISLAND CONTAINER --- */
        .swiss-island {
            --spring-easing: cubic-bezier(0.19, 1, 0.22, 1);
            position: relative;
            background-color: #050505;
            color: white;
            overflow: hidden;
            z-index: 50;
            transition: width 0.6s var(--spring-easing), height 0.6s var(--spring-easing), border-radius 0.6s var(--spring-easing), transform 0.2s ease;

            --mouse-x: 50%;
            --mouse-y: 50%;
        }

        /* States */
        .swiss-island.collapsed { width: 240px; height: 60px; border-radius: 999px; cursor: pointer; }
        .swiss-island.collapsed:hover { transform: scale(1.05); }
        .swiss-island.collapsed:active { transform: scale(0.95); }
        .swiss-island.expanded { width: 100%; height: 680px; border-radius: 32px; cursor: default; }

        /* --- GLOW EFFECT --- */
        .swiss-island.collapsed::before {
            content: "";
            position: absolute; inset: 0; border-radius: inherit;
            background: radial-gradient(200px circle at var(--mouse-x) var(--mouse-y), rgba(255, 255, 255, 0.15), transparent 100%);
            opacity: 0; transition: opacity 0.5s ease; pointer-events: none; z-index: 2;
        }
        .swiss-island.collapsed:hover::before { opacity: 1; }

        /* --- BUBBLE TRIGGER ZONE --- */
        .bubble-trigger-zone {
            position: absolute;
            top: 120px;
            left: 30px;
            right: 30px;
            bottom: 150px;
            z-index: 15;
            cursor: pointer;
        }

        /* --- SPEECH BUBBLE STYLES --- */
        .speech-bubble {
            position: absolute;
            padding: 12px 18px;
            border-radius: 24px;
            border-bottom-left-radius: 4px;
            background: rgba(255, 255, 255, 0.15);
            backdrop-filter: blur(12px);
            -webkit-backdrop-filter: blur(12px);
            border: 1px solid rgba(255, 255, 255, 0.3);
            box-shadow: 0 4px 15px rgba(0, 0, 0, 0.2), 0 0 15px rgba(255, 255, 255, 0.2), inset 0 1px 0 rgba(255, 255, 255, 0.2);
            color: white;
            font-size: 0.85rem;
            font-weight: 600;
            line-height: 1.4;
            letter-spacing: 0.02em;
            text-shadow: 0 1px 2px rgba(0,0,0,0.5);
            pointer-events: none;
            z-index: 100;
            max-width: 220px;

            animation: bubblePop 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
            transform-origin: bottom left;
        }

        .speech-bubble.fading {
            animation: bubbleDissolve 1.5s ease-out forwards;
        }

        @keyframes bubblePop {
            from { opacity: 0; transform: scale(0.5) translateY(10px); }
            to { opacity: 1; transform: scale(1) translateY(0); }
        }

        @keyframes bubbleDissolve {
            0% {
                opacity: 1;
                transform: scale(1) translateY(0);
                filter: blur(0px);
            }
            100% {
                opacity: 0;
                transform: scale(1.1) translateY(-20px);
                filter: blur(8px);
            }
        }

        /* Decorations */
        .island-bg-image {
            position: absolute; inset: 0; background-size: cover; background-position: center;
            filter: brightness(0.6) contrast(1.1); transition: opacity 0.5s ease 0.1s, background-image 0.5s ease;
        }
        .island-overlay {
            position: absolute; inset: 0; background: linear-gradient(to bottom, rgba(0, 0, 0, 0.3), rgba(0, 0, 0, 0) 40%, rgba(0, 0, 0, 0.9));
            transition: opacity 0.5s;
        }
        .scan-line {
            position: absolute; top: 0; left: 0; width: 100%; height: 100%;
            background: linear-gradient(to bottom, transparent, rgba(255, 255, 255, 0.05), transparent);
            transform: translateY(-100%); animation: scan 4s linear infinite; pointer-events: none; z-index: 1;
        }
        @keyframes scan { 0% { transform: translateY(-100%); } 100% { transform: translateY(100%); } }

        /* --- CAPSULE CONTENT --- */
        .capsule-content {
            position: absolute; inset: 0; display: flex; align-items: center; justify-content: space-between; padding: 0 1.5rem; transition: all 0.3s ease;
            z-index: 10;
        }
        .swiss-island.expanded .capsule-content { opacity: 0; transform: translateY(-20px); pointer-events: none; }
        .capsule-title { font-size: 0.875rem; font-weight: 700; text-transform: uppercase; letter-spacing: -0.02em; }
        .capsule-date { font-family: monospace; font-size: 0.75rem; opacity: 0.6; letter-spacing: 0.1em; }

        /* --- EXPANDED CARD CONTENT --- */
        .card-content {
            position: absolute; inset: 0; display: flex; flex-direction: column; padding: 1.5rem; opacity: 0; transform: translateY(20px); transition: all 0.5s ease 0.1s; pointer-events: none;
        }
        .swiss-island.expanded .card-content { opacity: 1; transform: translateY(0); pointer-events: auto; }

        /* Header */
        .card-header-row { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 1rem; position: relative; z-index: 30; }
        .main-title { font-size: 2.5rem; font-weight: 900; line-height: 0.9; letter-spacing: -0.05em; text-transform: uppercase; margin-bottom: 0.25rem; word-break: break-word; }
        .status-badge { display: flex; align-items: center; gap: 0.5rem; }
        .status-dot { width: 8px; height: 8px; background-color: #22c55e; border-radius: 50%; animation: pulse 2s infinite; }
        .status-text { font-family: monospace; font-size: 0.75rem; opacity: 0.8; letter-spacing: 0.15em; }
        @keyframes pulse { 0%, 100% { opacity: 1; transform: scale(1); } 50% { opacity: 0.5; transform: scale(0.8); } }

        .close-btn {
            width: 32px; height: 32px; border-radius: 50%; background: rgba(255, 255, 255, 0.2); border: none; color: white; display: flex; align-items: center; justify-content: center; cursor: pointer; backdrop-filter: blur(4px); transition: background 0.2s; flex-shrink: 0;
        }
        .close-btn:hover { background: white; color: black; }

        /* --- MIDDLE CONTENT AREA --- */
        .content-display-area {
            flex: 1;
            display: flex;
            align-items: flex-end;
            justify-content: center;
            padding-bottom: 20px;
            position: relative;
            z-index: 20;
            overflow: hidden;
            pointer-events: none;
        }

        .detail-glass-box {
            width: 100%;
            background: rgba(255, 255, 255, 0.08);
            backdrop-filter: blur(16px);
            -webkit-backdrop-filter: blur(16px);
            border: 1px solid rgba(255, 255, 255, 0.15);
