            box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.3);
            animation: slideUpFade 0.4s cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
            display: flex;
            flex-direction: column;
            gap: 12px;
            pointer-events: auto;
            max-height: 400px;
            overflow-y: auto;
        }

        @keyframes slideUpFade {
            from { opacity: 0; transform: translateY(20px) scale(0.95); }
