        }

        .nav-icon-btn.active {
            color: #fff;
            transform: translateY(-4px) scale(1.1);
            text-shadow: 0 0 12px rgba(255,255,255,0.6);
        }

        .nav-dot {
            width: 4px; height: 4px; background: white; border-radius: 50%;
            opacity: 0; transition: opacity 0.3s;
        }
        .nav-icon-btn.active .nav-dot { opacity: 1; }


        /* --- INNER CONTENT STYLES --- */
        .info-stack { display: flex; flex-direction: column; gap: 0.5rem; }
        .detail-row { display: flex; justify-content: space-between; padding: 4px 0; border-bottom: 1px solid rgba(255, 255, 255, 0.1); align-items: center;}
        .detail-label { opacity: 0.5; font-size: 0.7rem; text-transform: uppercase; letter-spacing: 0.05em; display: block; }
        .detail-value { font-family: monospace; font-size: 0.8rem; }
        .text-bold { font-weight: 700; }
        .text-desc { font-size: 0.75rem; margin-top: 0.25rem; opacity: 0.8; line-height: 1.4; }
        .tag-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; font-size: 0.75rem; }
        .tag-box { background: rgba(255, 255, 255, 0.1); padding: 8px; border-radius: 4px; }
        .span-2 { grid-column: span 2; }
        .mb-1 { margin-bottom: 4px; display: block; }

        .mood-box { display: flex; align-items: center; gap: 12px; }
        .mood-circle {
            width: 40px; height: 40px; border-radius: 50%;
            background: transparent; border: 1px solid rgba(255, 255, 255, 0.3);
            box-shadow: 0 0 8px rgba(255, 255, 255, 0.3);
            display: flex; align-items: center; justify-content: center; font-size: 1.2rem;
        }
        .mood-info { flex: 1; display: flex; flex-direction: column; }

        .search-list { display: flex; flex-direction: column; gap: 0.5rem; font-family: monospace; font-size: 0.75rem; }
        .search-header { color: rgba(255, 255, 255, 0.5); font-size: 0.7rem; }

        .search-item { display: flex; justify-content: space-between; align-items: flex-start; padding: 4px; border-radius: 4px; cursor: pointer; transition: background 0.2s; }

        .search-item:hover { background: rgba(255, 255, 255, 0.1); }

        .text-ellipsis {
            white-space: normal;
            overflow: visible;
            max-width: 180px;
            line-height: 1.3;
            word-break: break-all;
        }

        .text-faint { opacity: 0.5; white-space: nowrap; margin-left: 8px; }
        .text-danger { color: #fca5a5; }

        /* --- SETTINGS STYLES --- */
        .setting-input {
            width: 100%;
            background: rgba(0,0,0,0.3);
            border: 1px solid rgba(255,255,255,0.2);
            color: white;
            padding: 8px 12px;
            border-radius: 8px;
