            transition: border 0.2s;
        }
        .setting-input:focus { border-color: rgba(255,255,255,0.6); }

        .file-upload-label {
            display: flex;
            align-items: center;
            justify-content: center;
            width: 100%;
            padding: 10px;
            background: rgba(255, 255, 255, 0.1);
            border: 1px dashed rgba(255, 255, 255, 0.3);
