                },
                {
                    id: 'settings',
                    icon: <i className="fa-solid fa-gear"></i>,
                    title: 'SYSTEM SETTINGS',
                    content: (
                        <div className="info-stack">
                            <div className="detail-row" style={{ borderBottom: 'none', paddingBottom: 0 }}>
